#pragma once
#include "mikumikustudio/d3dx_dyn.hpp"
#include <cstdint>
#include <memory>
#include <string>
#include <vector>

namespace mikumikustudio::texture_prepare_cache {

// Calls the outer host import, so MMHack still observes the original filename
// and registers the returned texture. Its own native D3DX import is cached
// only inside this call. Without MMHack the same native path is used directly.
// Only the host's standard A8R8G8B8/managed, default-size, one-level requests
// (with optional autogenerated mipmaps) are eligible. The cache stores native
// resized pixels and original source metadata, keyed by source content, D3DX
// DLL identity, adapter/driver/caps, creation flags and usage. It keeps no live
// GPU objects. Hand-authored source mip chains and other requests stay native.
// Disk: <EXE>/Cache/Textures/<source stem>/<key>.mtc, globally capped at
// 128 files / 512 MiB, each decoded image at most 128 MiB. Corrupt files or any
// cache failure run the original loader. MMS_TEXTURE_CACHE_DISABLE=1 bypasses;
// MMS_TEXTURE_CACHE_DIR overrides the root for isolated diagnostics.
HRESULT Create(d3dx::FnCreateTexFromFileExW outer, IDirect3DDevice9* device,
    LPCWSTR path, UINT width, UINT height, UINT levels, DWORD usage,
    D3DFORMAT format, D3DPOOL pool, DWORD filter, DWORD mipFilter,
    D3DCOLOR colorKey, void* sourceInfo, void* palette, IDirect3DTexture9** output);

struct Statistics {
    std::uint64_t hits, nativeCalls, stores;
};
Statistics GetStatistics() noexcept;

// A model-local preparation scope. Files and disk caches are read only by the
// constructing thread. At most two CPU workers decode owned bytes; creation
// and MMHack registration remain in Create on the original loading thread.
// Existing GPU-pool entries should be omitted by the caller. Duplicate paths
// are collapsed. Unsupported formats, failures and budget overflow stay native.
// All exits join workers and release snapshots; no pixels survive this scope.
class Batch {
public:
    Batch(d3dx::FnCreateTexFromFileExW outer, IDirect3DDevice9* device,
          const std::vector<std::wstring>& paths) noexcept;
    ~Batch();
    Batch(const Batch&) = delete;
    Batch& operator=(const Batch&) = delete;
private:
    struct Impl;
    std::unique_ptr<Impl> impl_;
};
struct ParallelStatistics { std::uint64_t staged, decoded, used, diskReady, failures; };
ParallelStatistics GetParallelStatistics() noexcept;

} // namespace mikumikustudio::texture_prepare_cache
